INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p910930-acct301', 'stk-saa_00', 'ACCT 301', 'info', '{"desc": "بسم الله الرحمن الرحيم\n\nالسلام عليكم ورحمه الله وبركاته يا اخوان انا بدخل في الموضوع على طول انا منزل المادة ذي وتعبت وانا احاول اذاكرها ولا عرفت وخصوصا ان كلامها كثييييير وانا ايذا قريت الكتاب بكثره يتشتت فكري ولا اعرف اركز فمادري عن نصايحكم للاخوان الي خلصوها لا تبخلون علينا من خبرتكم ترا والله محتاجينها\nوالله تعبت من القراءه وخصوصا ان مدرسها بعد مهوب ذاك الزود\n\nولكم مني جزيل الشكر\n\nاخوكم\nsaa_00", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/acct-301/113027/1", "user": "saa_00", "ts": 1317364861000, "tid": 113027, "pn": 1}}', 1317364861000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p911039-acct301', 'stk-user3058', 'ACCT 301', 'info', '{"desc": "مين آخذتهآآ معه ،،؟؟\n\nبحكم خبرتي المتواضعة … المادة هذه و 302 آهم مواد الممحاسبة و اصعبهاا تقريبا لانهآآ هي المحاسبة فعليآآ … آنا آقول الكلام هذآآ عشآآن تركز عليهآآ\n\nبالنسبة لطريقة المذآكرة … المحآسبة مب مآدة حفظ يعني … آنت ركز اول شي على النقاط الاساسية في الشابتر يعني تعريف معين يتكلم عنه الشابتر كامل … نقاط معينة اساسية في الشابتر … و بعدهآآ حآول تفهم شرح المسآئل في الشبتر بعدهآآ ارجع حل البريف اكسرسايزز و الاكسرسايزز و كم بروبلم … و اختبر مدى فهمك … و بعدهآآ حاول تحل الاسئلية المقالية لانهآآ اهم شي يعني الجزء النظري في الشابتر\n\nو بعدين آستغرب لماا تقول فيهآآ دش كلام … يعني مقآرنة في المانجمنت و الماركيتنق و لا شي …\n\nموووفق ان شاء الله", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/acct-301/113027/3", "user": "user3058", "ts": 1317374275000, "tid": 113027, "pn": 3}}', 1317374275000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-p1317225-acct301', 'stk-fin_analyst', 'ACCT 301', 'info', '{"desc": "كلام الشباب صحيح\n\nوشيك عالكريكلوم واذا عندك اي اسألة بنساعدك\n\nانا انصح انك تخلص كورسات الماث والستات والانجلش بدري = مابيصير عندك دوام يوم خميس!\n\nوبتسهل عليك الاترام المتقدمة\n\nخطة الاخ G.MAN ممتازة\n\nولاتنسى ان مادة acct301 ماتنزل الا الترم الاول…عشان كذا يفضل تاخذ الاكاونتق 210 في الصيف\n\nولو تبا تكرف تقدر تاخذ معاها math131 عشان تفتك وتفتح الستات بس مابيكون الصيف سهل فما اانصح الا لو انك مجتهد", "type": "", "rel": 0, "lang": "", "book": "", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/topic/155120/4", "user": "FIN_Analyst", "ts": 1389179466000, "tid": 155120, "pn": 4}}', 1389179466000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user3328-acct301', 'stk-user3328', 'ACCT 301', 'doc', '{"docs": [{"id": "stk-dr-f98434", "n": "Dr. Yaser Ahmed Fallatah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "كورس acct301 - ترم 091\nكورس acct302 - ترم 092\n\nالتحضير\nأول المحاضره ولايمانع التأخير … والدكتور مايحرص على التأخير كثير\n\nطريقة الشرح\nجيده جدا … يفتح السلايدات ويشرح عليها ويسأل الطلاب باستمرار … ويخليهم يسألون بعضهم البعض\nويحل على السبوره المسائل المبهمه لدى الطلاب … ودائما يسأل الطلاب اذا مافهموا علشان يفهمهم\n\nالكويزات\nكوزات تافهه بعضها تحله وانت مغمض … والبعض الاخر يجي فيه أفكار بسيطه بس تفر مخك شوي\n\nالمياجر\nتجي دسمه غالبا … بس تعتمد على مدى فهمك\nودائما 10 اختيارات … ومعها مسائل وتعريفين أو ثلاثه ونادرا تخرج عن هالفورمات\nالاختيارات اغلبها من التست بانك … المسائل تكون اما شامله جدا أو واضحه جدا ونادرا تجي متوسطه\n\nالفاينلات\nنفس الكلام على المياجر\n\nالقريد النهائي\nB … الدكتور يحب مساعده الطلاب ونفسه خفيفه ويحاول بكل مايملك انه يخفف على الطالب\n\nالصوت\nواضح … وانجليزيته جيده لا بأس بها\n\nإضافات\nطبعا ما لطلاب المحاسبه الا هو … لذلك الحمد لله انه حبيب ومتساعد وشرحه جيدجدا\nدرجات المشاركه والواجبات غالبا تاخذها فل مارك اذا أديتها… والكوزات يعطيك درجه زياده دائما\nالله يوفقه ويجزاه خير …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p790065-acct301", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-yaser-ahmed-fallatah/98434/3", "user": "user3328", "ts": 1297700863000, "tid": 98434, "pn": 3}}]}', 1297700863000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-rkoni-acct301', 'stk-rkoni', 'ACCT 301', 'doc', '{"docs": [{"id": "stk-dr-f98434", "n": "Dr. Yaser Ahmed Fallatah", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "كورس acct301 - كورس acct302\n\nالتحضير : يحضر ومتعآون في حآلة الغيآب بدون عذر رسمي ومآ يدقق على التأخيـر كثير\n\nطريقة الشرح : مقبولـه … يضيع الوقت بالنقآشآت بدون التدرج بالشرح من النقطه الاسآسية الى الفرعيه … تفهم بصعوبه منه واختبآرآته ابد غير مطآبقه لشرحه …\n\nالكويزات : بعد كل تشآبتر ومتنوعه بين السهله والغريبة …\n\nالمياجر: تميل الى السهولة ولآكن غير متنآسقه مع شرحه … وغآلب مآ يكون سؤال عآم مثـل سوو فآينينشل ستآيتمينت … ويكون نص درجة الاختبآر عليهآ … ( مرآجعة الاسأله نهآية كل تشآبتر بالكتآب مهمه )\n\nالفاينلات : نفس الميجـر …\n\nالقريد النهائي: C\n\nالصوت: وآضح\n\nإضافات : الرجآل متعآون كثـير ويهتم لمصلحة الطلآب ولآكن للحين مآ قدر يتمكن من الكورس …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1044826-acct301", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-yaser-ahmed-fallatah/98434/4", "user": "RKONI", "ts": 1338015419000, "tid": 98434, "pn": 4}}]}', 1338015419000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-waleedx11-acct301', 'stk-waleedx11', 'ACCT 301', 'doc', '{"docs": [{"id": "stk-dr-f98437", "n": "Dr. Mohammad Talha", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ACCT301 Term171\n\nالتحضير : بالسيريال نمبر ، أول ما يدخل الكلاس.\nطريقة الشرح : أقسم بمن رفع السماوات والأرض إن الشرح زباااااااالة … مجرد قراية السلايدات ولغة غير مفهومة\n\nالكويزات : تي بي\nالمياجر: تي بي\nالفاينلات : تي بي\nالقريد النهائي: والله لو في حاجة أقل من F يستاهلها 😠\nالصوت: يجيب النوم وواطي في كثير من الأحيان وحتى لو يعليه ما تفهم من الاكسنت المضروب شيء.\nإضافات :\n١- نهاية السمستر قريب الفاينل شوي ويبوس رجولنا عشان نقييمه كويس ولما يسكر التقييم يقلب 180 درجة .\n٢- المادة فيها بروجكت عليه 15% من الكورس خسف أم أمنا فيه وعطانا درجته بعد التقييم بالعنية.\n٣- ألفاظه ألفاظ لا تليق بمستوى دكتور أبدا يسألك واذا جاوبت يهزأ فيك واحتمال يهينك ويضحك الكلاس عليك.\n٤- اذا رحت له المكتب توقع منه يصرفك ويطردك حتى لو في الساعات المكتبية.\n٥- مايمشيك الا اذا تمصلحت معه ومدحت فيه.\n\nأنصح أي شخص يبي ينزلها يتأخر سنة كاملة ولا ينزلها معه خصوصًا لو كنت طالب أكاونتنق وتبي تفهم لأن المادة حرفيًا سيلف ستدي معه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1485508-acct301", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammad-talha/98437/25", "user": "waleedx11", "ts": 1515091810000, "tid": 98437, "pn": 25}}]}', 1515091810000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9921-acct301', 'stk-user9921', 'ACCT 301', 'doc', '{"docs": [{"id": "stk-dr-f98437", "n": "Dr. Mohammad Talha", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "Acct 301\nTerm 171\n\nالتحضير :\nيحضر على السيريال ولو سرحت ما يحضرك ثانية، طبعاً ما كان فيه درجات على الحضور\n\nطريقة الشرح :\nما يشرح أصلاً ، شرحه ممكن تستفيد منه بنسبة 5 % ، الباقي يقرا في السلايدات ويهزّأ في الطلاب اللي يسألوه ، كل كلاس لازم يستلم واحد ويسفل فيه والطلاب يضحكون بس!\nلو ما كنا مجبورين ما سجلنا معاه\n\nالكويزات :\nTB حتى ترتيب الاجابات ما يغيرها ، يحذف اسوأ واحد\n\nالمياجر:\nTB ومسائل ، بالنسبة للمسائل يعطيك مسائل مشابهة تحلها بس ممكن يغدر فيك ويجيب شي جديد\nافرج الميجر الثاني 90%\n\nالفاينلات :\nنفس طريقة المياجر\n\nالقريد النهائي: C\n\nالصوت:\nالاكسنت حقه مره تعبان ، صحيح الاكسنت الهندي صعب بس هذا تجاوزهم بمراااااحل … ممكن يقول كلمه وتفهم ايش يقصد بها بعد يومين\n\nإضافات :\nاذا حدك الزمن عليه استمتع بوقتك في الكلاس وحاول تحفظ التي بي عشان القريد و لا تنتظر شرح منه", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1485777-acct301", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammad-talha/98437/26", "user": "user9921", "ts": 1515449895000, "tid": 98437, "pn": 26}}]}', 1515449895000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-user9840-acct301', 'stk-user9840', 'ACCT 301', 'doc', '{"docs": [{"id": "stk-dr-f98437", "n": "Dr. Mohammad Talha", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "ACCT301 Term171\n\nالتحضير : بالسيريال نمبر ، أول ما يدخل الكلاس.\nطريقة الشرح : من كلام الشعب خفت منه حييل - لكن على ارض الواقع شرحه مقبول + شره كويس في الكونسبت لكن لاتخليه يحل مسائل 👍\n\nالكويزات : تي بي - كل جابترين بكويز مكون من 10 اسئلة او 10 كويزات كما يقول هههههههه\nالمياجر: الخيارات تي بي - والمسائل مدري من وين يجيبهم - مسائل الميجر الاول كانت صعبة لكن الميجر الثاني كان سهل وكان الافرج عالي نتيجة لديل 👍\nالفاينلات : نفس طريقة المياجر\nالقريد النهائي: C+ وبدفه لل B\nالصوت: هندي لكن اكسنته مفهوم .\nإضافات :\n١- الافاليويشن شيء مقدس عنده .\n٢- المادة فيها بروجكت عليه 15% خفس الطلاب لكن في المقابل كانت درجات المياجر عالية فهي معادلة.\n٣- انسان مرح وممتع لكن بعض الطلاب الله يهديهم يحبون يضحكون لو طقطق على غيرهم لكن لو يطقطق عليهم بيزعلون ويشخصون الموضوع.\n٤- عامل هالدكتور كأنه شيبة يعني سايسه .\n5- عمل شيء خله بعض اعالي القوم سافلها وسافلها عاليها …\n6- الكورس هذا كرهني بالتي بي لما نقول تي بي مش معناه سهل - كل جابتر فيه اكثرر من 120 سؤال بين كونسبت ومسائل\n\nنزلوا عنده ولا داعي للقلق …", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1485829-acct301", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mohammad-talha/98437/28", "user": "user9840", "ts": 1515511056000, "tid": 98437, "pn": 28}}]}', 1515511056000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
INSERT INTO posts (id, uid, code, sec, data, ts, updated, st) VALUES ('stk-doc-hard-worker-acct301', 'stk-hard-worker', 'ACCT 301', 'doc', '{"docs": [{"id": "stk-dr-f172138", "n": "Dr. Mahmud Hossain", "en": "", "img": "", "e": "", "bld": "", "room": "", "d": "151 ACCT301\n152 ACCT302\nأخذت عنده هالمادتين صراحة الدكتور شرحه للأسف سيء جدا لدرجة ان الواحد يفقد تركيزه ولا يقدر يركز معه لنهاية الكلاس وأعتقد الشيء ذا يرجع لطريقة تدريسه في استراليا على كلامه يقول كان هو يعطي ال theories and concept ويكون فيه مدرس أخر لنفس المادة يشرح ال Accounting practice وحل المسائل ،،، احنا هنا عانينا معاه لانه مو متعود يحل بالسبورة ويشرح لنا فكان شرحه على السبورة قليل والمحاسبة تعتمد على حل المسائل بشكل كبير\nيعني من وجهة نظري أفضل دكتور يشرح لي كيف أحل المسائل ويترك لي جزء النظريات والقراءة لي أقرأها في البيت\n\nنظرا لطريقته في الشرح اللي ماتناسبت معنا كنا نحتاج وقت أكبر في السيلف ستدي\n\nبالنسبة لأسئلته كان تقريبا يجيب أسئلة مشابهة للبروبليمز أخر الكتاب و بعض الأسئلة يحط فيها شوي تريكات،، يعني اللي يذاكر أسئلة الكتاب ويفهمها صح ان شاء الله يجيب قريد طيب\nتقييمي للدكتور D+\nقريدي معاه B في ACCT301\nB+ في ACCT302", "hours": [], "teach": 0, "grade": 0, "pid": "stk-p1461143-acct301", "imp": {"src": "stkfupm", "url": "https://community.stkfupm.com/t/dr-mahmud-hossain/172138/3", "user": "HARD-WORKER", "ts": 1477517099000, "tid": 172138, "pn": 3}}]}', 1477517099000, 1794828442, 'pub') ON CONFLICT (id) DO UPDATE SET data = EXCLUDED.data, ts = EXCLUDED.ts, updated = EXCLUDED.updated;
